function maximumScore(a, b, c) {
  // Simulate the game, always taking a stone from the two biggest piles.
  const piles = [a, b, c];
  let score = 0;
  for (;;) {
    piles.sort((x, y) => y - x);
    if (piles[1] === 0) return score;
    piles[0]--;
    piles[1]--;
    score++;
  }
}

