function generate(rand, size) {
  const limit = size === 'large' ? 100000 : 12;
  const pick = () => 1 + Math.floor(rand() * limit);
  const piles = [pick(), pick(), pick()];
  if (rand() < 0.3) {
    // Make one pile dominate the other two.
    const index = Math.floor(rand() * 3);
    piles[index] = limit - Math.floor(rand() * Math.max(1, Math.floor(limit / 10)));
    for (let i = 0; i < 3; i++) if (i !== index) piles[i] = 1 + Math.floor(rand() * Math.max(1, Math.floor(limit / 3)));
  }
  return piles;
}
